from boltons.iterutils import split_iter

def test_maxsplit_zero_list():
    src = [1, None, 2]
    result = list(split_iter(src, maxsplit=0))
    print(f"List result: {result}")
    assert result == [[1, None, 2]]

def test_maxsplit_zero_iter():
    src = iter([1, None, 2])
    result = list(split_iter(src, maxsplit=0))
    print(f"Iter result: {result}")
    assert result == [[1, None, 2]]

if __name__ == "__main__":
    try:
        test_maxsplit_zero_list()
        print("test_maxsplit_zero_list passed")
    except Exception as e:
        print(f"test_maxsplit_zero_list failed: {e}")

    try:
        test_maxsplit_zero_iter()
        print("test_maxsplit_zero_iter passed")
    except Exception as e:
        print(f"test_maxsplit_zero_iter failed: {e}")

